mapper.select:
/*selectBuyerMpStStockGoodsList*/
SELECT X.BELOW_COMORG_CODE , X.BUYER , X.ITEM_GUBUN , X.BUYER_ITEM_NO , X.DESCRIPTION , X.SPECIFICATION , X.UNIT_MEASURE , X.MAKER_NAME , X.STOCK_QTY , X.CONTRACT_NO , X.CONTRACT_SEQ FROM ( SELECT CQDT.BELOW_COMORG_CODE , CQDT.BUYER , DECODE(COD2.CODE,NULL,'N','S') AS ITEM_GUBUN /* N:일반, S:재고 */ , BYIT.BUYER_ITEM_NO , BYIT.DESCRIPTION_LOC AS DESCRIPTION , BYIT.SPECIFICATION , BYIT.UNIT_MEASURE , CQDT.MAKER_NAME , NVL(STCK.TOT_QTY,0) AS STOCK_QTY , CQDT.CONTRACT_NO , CQDT.CONTRACT_SEQ , ROW_NUMBER() OVER(PARTITION BY CQDT.BUYER_ITEM_NO ORDER BY CQDT.BUYER, CQDT.CONTRACT_NO DESC, CQDT.CONTRACT_SEQ DESC) AS MAX_CONT FROM ICOMBYIT BYIT /* 구매사카탈로그 상품정보 */ , ICOMCQDT CQDT /* 구매사별 계약서 가격정보 */ , BUYER_STOCK STCK /* 구매사 재고 관리 테이블 */ , ICOMCOD2 COD2 /* 회사별 코드관리 */ WHERE 1=1 AND BYIT.STATUS ^= 'D' AND BYIT.PRODUCT_CLOSE_FLAG IN ('N','T') AND BYIT.BUYER = #{st_comorg_code} AND BYIT.BUYER = CQDT.BUYER AND BYIT.BUYER_ITEM_NO = CQDT.BUYER_ITEM_NO AND CQDT.STATUS ^= 'D' AND CQDT.BELOW_COMORG_CODE = DECODE((SELECT COUNT(*) FROM ICOMCQDT WHERE BUYER = CQDT.BUYER AND BUYER_ITEM_NO = CQDT.BUYER_ITEM_NO AND STATUS ^= 'D' AND BELOW_COMORG_CODE = #{st_com_code}), 0, 'ABOVE', #{st_com_code}) AND #{st_com_code} = STCK.BUYER(+) AND CQDT.BUYER_ITEM_NO = STCK.ITEM_NO(+) AND STCK.STATUS(+) ^= 'D' AND #{st_com_code} = COD2.COMPANY_CODE(+) AND COD2.TYPE(+) = 'STCK' AND COD2.FLAG(+) = 'Y' AND CQDT.BUYER_ITEM_NO = COD2.CODE(+) AND 0 = CASE WHEN #{st_item_gubun} = 'T' THEN 0 WHEN #{st_item_gubun} = 'N' THEN (SELECT COUNT(*) FROM ICOMCOD2 WHERE COMPANY_CODE = #{st_com_code} AND TYPE = 'STCK' AND FLAG = 'Y' AND CODE = CQDT.BUYER_ITEM_NO) WHEN #{st_item_gubun} = 'S' THEN (SELECT DECODE(COUNT(*), 0, 1, 0) FROM ICOMCOD2 WHERE COMPANY_CODE = #{st_com_code} AND TYPE = 'STCK' AND FLAG = 'Y' AND CODE = CQDT.BUYER_ITEM_NO) ELSE 1 END
AND CQDT.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND CQDT.DESCRIPTION LIKE '%' || #{st_description} || '%'
AND CQDT.SPECIFICATION LIKE '%' || #{st_specification} || '%'
) X WHERE X.MAX_CONT = 1 /* 계약데이터는 마지막 계약을 기준으로 한다 */ ORDER BY X.BUYER_ITEM_NO
